+        </button>
+      </div>
+
+      <p class="status" id="status" aria-live="polite"></p>
+    </section>
+  </main>
+
+  <dialog id="delete-dialog" aria-labelledby="delete-title" aria-describedby="delete-desc">
+    <div class="dialog-body">
+      <div class="dialog-icon" aria-hidden="true">!</div>
+
+      <div class="dialog-copy">
+        <h2 id="delete-title">Delete this image?</h2>
+        <p id="delete-desc">
+          This will remove the image from your library. This action cannot be undone.
+        </p>
+      </div>
+
+      <div class="dialog-actions">
+        <button class="secondary" type="button" id="cancel-button">Cancel</button>
+        <button class="danger" type="button" id="confirm-button">Delete</button>
