<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Image Preview</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b0f14;
      --panel: #121821;
      --panel-2: #182230;
      --text: #e7edf5;
      --muted: #95a3b8;
      --border: rgba(255, 255, 255, 0.08);
      --accent: #7c9cff;
      --danger: #ff6b6b;
      --shadow: 0 24px 70px rgba(0, 0, 0, 0.5);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      background:
        radial-gradient(circle at top, rgba(124, 156, 255, 0.18), transparent 32%),
        linear-gradient(180deg, #0c1016 0%, #090c11 100%);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      padding: 24px;
    }

    .page {
      width: min(920px, 100%);
      display: grid;
      gap: 18px;
      justify-items: center;
    }

    .card {
      width: min(640px, 100%);
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.02), rgba(255, 255, 255, 0.01));
      border: 1px solid var(--border);
      border-radius: 24px;
      box-shadow: var(--shadow);
      padding: 18px;
      backdrop-filter: blur(12px);
    }

    .preview {
      display: grid;
      gap: 16px;
    }

    .image-frame {
      overflow: hidden;
      border-radius: 18px;
      background: var(--panel-2);
      border: 1px solid var(--border);
    }

    .image-frame img {
      display: block;
      width: 100%;
      height: auto;
    }

    .meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      flex-wrap: wrap;
    }

    .title {
      margin: 0;
      font-size: 1.05rem;
      font-weight: 650;
      letter-spacing: 0.01em;
    }

    .subtitle {
      margin: 6px 0 0;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .trigger,
    .secondary,
    .danger {
      appearance: none;
      border: 0;
      border-radius: 999px;
      padding: 0.9rem 1.2rem;
      font: inherit;
      font-weight: 650;
      cursor: pointer;
      transition: transform 0.18s ease, background 0.18s ease, box-shadow 0.18s ease, opacity 0.18s ease;
    }

    .trigger {
      background: linear-gradient(180deg, #2a3550, #1d2638);
      color: var(--text);
      box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.08);
    }

    .secondary {
      background: transparent;
      color: var(--text);
      box-shadow: inset 0 0 0 1px var(--border);
    }

    .danger {
      background: linear-gradient(180deg, #ff7a7a, #e84e4e);
      color: #fff;
    }

    .trigger:hover,
    .secondary:hover,
    .danger:hover {
      transform: translateY(-1px);
    }

    .trigger:focus-visible,
    .secondary:focus-visible,
    .danger:focus-visible,
    dialog button:focus-visible {
      outline: 3px solid rgba(124, 156, 255, 0.45);
      outline-offset: 3px;
    }

    .status {
      min-height: 1.5rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    dialog {
      width: min(440px, calc(100% - 32px));
      border: 1px solid var(--border);
      border-radius: 24px;
      padding: 0;
      background: linear-gradient(180deg, #141b26, #0f141d);
      color: var(--text);
      box-shadow: var(--shadow);
    }

    dialog::backdrop {
      background: rgba(5, 8, 12, 0.72);
      backdrop-filter: blur(6px);
    }

    .dialog-body {
      padding: 24px;
      display: grid;
      gap: 18px;
    }

    .dialog-icon {
      width: 48px;
      height: 48px;
      border-radius: 14px;
      display: grid;
      place-items: center;
      background: rgba(255, 107, 107, 0.12);
      color: #ff8f8f;
      font-size: 1.5rem;
    }

    .dialog-copy h2 {
      margin: 0;
      font-size: 1.2rem;
    }

    .dialog-copy p {
      margin: 10px 0 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 12px;
      flex-wrap: wrap;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }
  </style>
</head>
<body>
  <main class="page">
    <section class="card preview" aria-labelledby="image-title">
      <div class="image-frame">
        <img
          src="https://images.unsplash.com/photo-1516321497487-e288fb19713f?auto=format&fit=crop&w=1200&q=80"
          alt="A laptop on a desk with a softly lit workspace."
        >
      </div>

      <div class="meta">
        <div>
          <h1 class="title" id="image-title">Workspace preview</h1>
          <p class="subtitle">Stored in your image library.</p>
        </div>

        <button class="trigger" type="button" aria-haspopup="dialog" aria-controls="delete-dialog">
          Delete image
        </button>
      </div>

      <p class="status" id="status" aria-live="polite"></p>
    </section>
  </main>

  <dialog id="delete-dialog" aria-labelledby="delete-title" aria-describedby="delete-desc">
    <div class="dialog-body">
      <div class="dialog-icon" aria-hidden="true">!</div>

      <div class="dialog-copy">
        <h2 id="delete-title">Delete this image?</h2>
        <p id="delete-desc">
          This will remove the image from your library. This action cannot be undone.
        </p>
      </div>

      <div class="dialog-actions">
        <button class="secondary" type="button" id="cancel-button">Cancel</button>
        <button class="danger" type="button" id="confirm-button">Delete</button>
      </div>
    </div>
  </dialog>

  <script>
    const dialog = document.getElementById('delete-dialog');
    const openButton = document.querySelector('.trigger');
    const cancelButton = document.getElementById('cancel-button');
    const confirmButton = document.getElementById('confirm-button');
    const status = document.getElementById('status');

    let lastFocusedElement = null;

    function openDialog() {
      lastFocusedElement = document.activeElement;
      dialog.showModal();
      cancelButton.focus();
    }

    function closeDialog() {
      dialog.close();
      if (lastFocusedElement && typeof lastFocusedElement.focus === 'function') {
        lastFocusedElement.focus();
      }
    }

    openButton.addEventListener('click', openDialog);
    cancelButton.addEventListener('click', closeDialog);

    confirmButton.addEventListener('click', () => {
      status.textContent = 'Image deleted from your library.';
      closeDialog();
    });

    dialog.addEventListener('cancel', () => {
      closeDialog();
    });

    dialog.addEventListener('click', (event) => {
      if (event.target === dialog) {
        closeDialog();
      }
    });
  </script>
</body>
</html>
